test_setup_files.behavior_test.js:
const assert = require('assert');
const path = require('path');
const { resolveSafe } = require('./safepath.js');

const base = path.resolve('data');

const ok = resolveSafe(base, 'docs/guide.md');
assert.strictEqual(path.resolve(ok), path.join(base, 'docs', 'guide.md'));

// internal ../ that stays inside must be fine
const okUp = resolveSafe(base, 'docs/../readme.md');
assert.strictEqual(path.resolve(okUp), path.join(base, 'readme.md'));

for (const evil of ['../secret.txt', '..', 'a/../../b', '../../etc/passwd']) {
  assert.throws(() => resolveSafe(base, evil), /outside/i, `must reject ${evil}`);
}
// absolute user paths must not bypass the base
assert.throws(() => resolveSafe(base, '/etc/passwd'), /outside/i, 'absolute path must be rejected');
console.log('PASS');

reference_solution.safepath.js:
const path = require('path');

/**
 * Resolve a user-supplied relative path inside baseDir.
 * Must never escape baseDir.
 */
function resolveSafe(baseDir, userPath) {
  const root = path.resolve(baseDir);
  const resolved = path.resolve(root, userPath);
  if (resolved !== root && !resolved.startsWith(root + path.sep)) {
    throw new Error(`path escapes outside base directory: ${userPath}`);
  }
  return resolved;
}

module.exports = { resolveSafe };

files.safepath.js:
const path = require('path');

function resolveSafe(baseDir, userPath) {
  if (userPath.startsWith('..')) {
    throw new Error(`path escapes outside base directory: ${userPath}`);
  }
  return path.join(baseDir, userPath);
}

module.exports = { resolveSafe };
